<?php
declare(strict_types=1);
namespace Nexus\Features\Inventario\Infrastructure;
use Nexus\Features\Inventario\Domain\InventarioRepository;
use Nexus\Shared\Domain\ValueObject\Cedula;

final class PdoInventarioRepository implements InventarioRepository
{
    private \PDO $pdo;
    public function __construct(\PDO $p){$this->pdo=$p;}
    public function listarEquipos():array{$q=$this->pdo->query("SELECT e.id_equipo,e.nombre_equipo,e.categoria_equipo,e.descripcion,e.marca_equipo,e.cantidad_del_equipo,GREATEST(e.cantidad_del_equipo-COALESCE((SELECT SUM(CAST(SUBSTRING_INDEX(p.recursos_solicitados,' ',1) AS UNSIGNED)) FROM PRESTAMO p WHERE p.id_equipo=e.id_equipo AND p.esta_activo=1 AND p.estado IN ('Solicitado','Activo')),0),0) cantidad_disponible,e.esta_activo,e.estado_equipo,e.fecha_agregado,e.id_ubicacion,u.seccion_inventario FROM EQUIPO e INNER JOIN UBICACION u ON u.id_ubicacion=e.id_ubicacion WHERE e.esta_activo=1 AND e.estado_equipo<>'Baja' ORDER BY e.id_equipo DESC");return $q->fetchAll(\PDO::FETCH_ASSOC);}
    public function ubicacionExiste(int $id,bool $activa=false):bool{$sql='SELECT 1 FROM UBICACION WHERE id_ubicacion=?'.($activa?' AND esta_activa=1':'');$q=$this->pdo->prepare($sql);$q->execute([$id]);return (bool)$q->fetchColumn();}
    public function crearEquipo(array $d,Cedula $autor):int{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare('INSERT INTO EQUIPO(nombre_equipo,categoria_equipo,descripcion,marca_equipo,cantidad_del_equipo,esta_activo,estado_equipo,fecha_agregado,id_ubicacion) VALUES(?,?,?,?,?,?,?,CURDATE(),?)');$q->execute([$d['nombre'],$d['tipo'],$d['observaciones'],$d['marca'],$d['cantidad'],$d['activo'],$d['estadoBase'],$d['seccionId']]);$id=(int)$this->pdo->lastInsertId();$this->historialEquipo($id,'Alta de equipo','Equipo "'.$d['nombre'].'" creado.',$autor);$this->pdo->commit();return $id;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function editarEquipo(int $id,array $d,Cedula $autor):bool{$q=$this->pdo->prepare('SELECT 1 FROM EQUIPO WHERE id_equipo=? AND esta_activo=1');$q->execute([$id]);if(!$q->fetchColumn())return false;$this->pdo->beginTransaction();try{$q=$this->pdo->prepare('UPDATE EQUIPO SET nombre_equipo=?,categoria_equipo=?,descripcion=?,marca_equipo=?,estado_equipo=?,id_ubicacion=? WHERE id_equipo=?');$q->execute([$d['nombre'],$d['tipo'],$d['observaciones'],$d['marca'],$d['estado'],$d['seccionId'],$id]);$this->historialEquipo($id,'Modificación de equipo','Datos generales del equipo actualizados.',$autor);$this->pdo->commit();return true;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function trasladarEquipo(int $id,int $destino,Cedula $autor):?bool{$q=$this->pdo->prepare('SELECT e.nombre_equipo,e.id_ubicacion,u.seccion_inventario FROM EQUIPO e INNER JOIN UBICACION u ON u.id_ubicacion=e.id_ubicacion WHERE e.id_equipo=?');$q->execute([$id]);$e=$q->fetch(\PDO::FETCH_ASSOC);if(!$e)return null;if((int)$e['id_ubicacion']===$destino)return false;$q=$this->pdo->prepare('SELECT seccion_inventario FROM UBICACION WHERE id_ubicacion=?');$q->execute([$destino]);$nombre=(string)$q->fetchColumn();$this->pdo->beginTransaction();try{$q=$this->pdo->prepare('UPDATE EQUIPO SET id_ubicacion=? WHERE id_equipo=?');$q->execute([$destino,$id]);$this->historialEquipo($id,'Traslado de equipo',sprintf('Equipo "%s" trasladado de "%s" a "%s".',$e['nombre_equipo'],$e['seccion_inventario'],$nombre),$autor);$this->pdo->commit();return true;}catch(\Throwable $x){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $x;}}
    public function bajaEquipo(int $id,Cedula $autor):?bool{$q=$this->pdo->prepare('SELECT e.nombre_equipo,e.esta_activo,e.estado_equipo,u.seccion_inventario FROM EQUIPO e INNER JOIN UBICACION u ON u.id_ubicacion=e.id_ubicacion WHERE e.id_equipo=?');$q->execute([$id]);$e=$q->fetch(\PDO::FETCH_ASSOC);if(!$e)return null;if(!(int)$e['esta_activo']||$e['estado_equipo']==='Baja')return false;$this->pdo->beginTransaction();try{$q=$this->pdo->prepare("UPDATE EQUIPO SET esta_activo=0,estado_equipo='Baja' WHERE id_equipo=?");$q->execute([$id]);$this->historialEquipo($id,'Baja de equipo',sprintf('Equipo "%s" dado de baja desde "%s".',$e['nombre_equipo'],$e['seccion_inventario']),$autor);$this->pdo->commit();return true;}catch(\Throwable $x){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $x;}}
    public function esquemaUbicacionesActualizado():bool{$q=$this->pdo->query("SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='UBICACION' AND COLUMN_NAME='esta_activa'");return (bool)$q->fetchColumn();}
    public function listarUbicaciones():array{$q=$this->pdo->query("SELECT u.id_ubicacion,u.seccion_inventario,COUNT(e.id_equipo) cantidad_equipos FROM UBICACION u LEFT JOIN EQUIPO e ON e.id_ubicacion=u.id_ubicacion AND e.esta_activo=1 AND e.estado_equipo<>'Baja' WHERE u.esta_activa=1 GROUP BY u.id_ubicacion,u.seccion_inventario ORDER BY u.seccion_inventario");return $q->fetchAll(\PDO::FETCH_ASSOC);}
    public function crearUbicacion(string $n,Cedula $autor):int{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare('INSERT INTO UBICACION(seccion_inventario) VALUES(?)');$q->execute([$n]);$id=(int)$this->pdo->lastInsertId();$this->historialUbicacion($id,'Alta de sección','Seccion "'.$n.'" creada.',$autor);$this->pdo->commit();return $id;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function renombrarUbicacion(int $id,string $n,Cedula $autor):bool{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare('UPDATE UBICACION SET seccion_inventario=? WHERE id_ubicacion=? AND esta_activa=1');$q->execute([$n,$id]);if(!$q->rowCount()){$this->pdo->rollBack();return false;}$this->historialUbicacion($id,'Modificación de sección','Sección renombrada a "'.$n.'".',$autor);$this->pdo->commit();return true;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function bajaUbicacion(int $id,?int $destino,Cedula $autor):?array{$q=$this->pdo->prepare('SELECT seccion_inventario,esta_activa FROM UBICACION WHERE id_ubicacion=?');$q->execute([$id]);$u=$q->fetch(\PDO::FETCH_ASSOC);if(!$u)return null;if(!(int)$u['esta_activa'])return ['sinCambios'=>true,'cantidad'=>0];$q=$this->pdo->prepare("SELECT id_equipo,nombre_equipo FROM EQUIPO WHERE id_ubicacion=? AND esta_activo=1 AND estado_equipo<>'Baja'");$q->execute([$id]);$equipos=$q->fetchAll(\PDO::FETCH_ASSOC);if($equipos&&$destino===null)throw new \Nexus\Shared\DomainException('Elegí una sección destino para trasladar los equipos antes de eliminar.');$nombreDestino='';if($equipos){$q=$this->pdo->prepare('SELECT seccion_inventario FROM UBICACION WHERE id_ubicacion=? AND esta_activa=1');$q->execute([$destino]);$v=$q->fetchColumn();if($v===false)throw new \Nexus\Shared\DomainException('No existe una sección destino activa para trasladar los equipos.',404);$nombreDestino=(string)$v;}$this->pdo->beginTransaction();try{if($equipos){$q=$this->pdo->prepare("UPDATE EQUIPO SET id_ubicacion=? WHERE id_ubicacion=? AND esta_activo=1 AND estado_equipo<>'Baja'");$q->execute([$destino,$id]);foreach($equipos as $e)$this->historialEquipo((int)$e['id_equipo'],'Traslado de equipo',sprintf('Equipo "%s" trasladado de "%s" a "%s" por eliminación de sección.',$e['nombre_equipo'],$u['seccion_inventario'],$nombreDestino),$autor);}$q=$this->pdo->prepare('UPDATE UBICACION SET esta_activa=0 WHERE id_ubicacion=?');$q->execute([$id]);$desc=$equipos?sprintf('Sección "%s" dada de baja. %d equipo%s trasladado%s a "%s".',$u['seccion_inventario'],count($equipos),count($equipos)===1?'':'s',count($equipos)===1?'':'s',$nombreDestino):'Seccion "'.$u['seccion_inventario'].'" dada de baja.';$this->historialUbicacion($id,'Baja de sección',$desc,$autor);$this->pdo->commit();return ['cantidad'=>count($equipos),'destino'=>$destino];}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    private function historialEquipo(int $id,string $categoria,string $descripcion,Cedula $autor):void{$q=$this->pdo->prepare('INSERT INTO HISTORIAL_EQUIPO(categoria,descripcion,id_equipo,autor_cedula,autor_nombre) VALUES(?,?,?,?,?)');$q->execute([$categoria,$descripcion,$id,$autor->value(),$this->nombreAutor($autor)]);}
    private function historialUbicacion(int $id,string $categoria,string $descripcion,Cedula $autor):void{$q=$this->pdo->prepare('INSERT INTO HISTORIAL_UBICACION(categoria,descripcion,id_ubicacion,autor_cedula,autor_nombre) VALUES(?,?,?,?,?)');$q->execute([$categoria,$descripcion,$id,$autor->value(),$this->nombreAutor($autor)]);}
    private function nombreAutor(Cedula $autor):string{$q=$this->pdo->prepare("SELECT TRIM(CONCAT(nombre,' ',apellido)) FROM USUARIO WHERE cedula=?");$q->execute([$autor->value()]);$nombre=trim((string)$q->fetchColumn());return $nombre!==''?$nombre:'Usuario '.$autor->value();}
}
